import numpy as np
from scipy.optimize import least_squares
def run(feat):
    def loss(th):
        A=feat(th); c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]; return dP_dt-A@c
    best=None
    for w0 in np.linspace(0.2,0.8,25):
        try:
            r=least_squares(loss,[w0])
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    A=feat(best.x); c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    return np.mean(best.fun**2)/np.var(dP_dt), best.x, np.round(c,4)
